[HttpGet]
public async Task<IActionResult> Get(CancellationToken ct)
{
    var row = await store.EnsureAsync(db, ct);
    return Ok(new { settings = await PublicSettingsAsync(row, ct), defaults = Defaults() });
}

internal object Defaults() => new
{
    categories = ClientSettingsStore.DefaultCategories,
    baseDownloadPath = store.DefaultDownloadDirectory,
    clientType = "builtin",
};

internal async Task<Dictionary<string, object?>> PublicSettingsAsync(ClientSetting s, CancellationToken ct)
{
    var config = await store.GetConfigAsync(ct);
    var cap = config.MaxStorageBytes;
    var hasFolder = config.DownloadRoot is not null;
    // What the running queue enforces now (its in-memory limits), so the UI never guesses the window/setting rule.
    var effective = DownloadLimits.Effective(DownloadWindows.Evaluate(limits.Windows, time.GetLocalNow()),
        limits.MaxActiveOverride, engineOptions.CurrentValue.MaxActiveDownloads);
    return new Dictionary<string, object?>
    {
        ["clientType"] = config.ClientType,
        ["externalClientType"] = config.ExternalClientType,
        ["externalClientsEnabled"] = store.ExternalClientsEnabled,
        ["host"] = s.Host,
        ["username"] = s.Username,
        ["hasPassword"] = config.HasPassword,
        ["category"] = s.Category,
        ["savePath"] = s.SavePath,
        ["baseDownloadPath"] = s.BaseDownloadPath,
        ["maxStorageBytes"] = cap,
        ["maxStorageGb"] = cap is { } c ? Math.Round(c / 1e9 * 10) / 10 : 0,
        ["storageCapConfigured"] = cap is not null,
        ["setupComplete"] = hasFolder && cap is > 0,
        ["verboseDiagnostics"] = s.VerboseDiagnostics == true,
        ["preferredResolution"] = SettingsDefaults.ResolutionOrDefault(s.PreferredResolution),
        ["audioLanguage"] = ReleaseLanguage.NormalizePreference(s.AudioLanguage) ?? ReleaseLanguage.Auto,
        ["automationIntervalMinutes"] = SettingsDefaults.AutomationIntervalOrDefault(s.AutomationIntervalMinutes),
        ["maxActiveDownloads"] = s.MaxActiveDownloads is >= DownloadLimits.MinActiveDownloads and <= DownloadLimits.MaxActiveDownloads
            ? s.MaxActiveDownloads : DefaultMaxActive(),
        ["maxActiveDownloadsDefault"] = DefaultMaxActive(),
        ["effectiveMaxActive"] = effective.MaxActive,
        ["maxActiveSource"] = effective.Source,
        ["downloadWindows"] = DownloadWindows.Parse(s.DownloadWindows),
        ["downloadWindowOpen"] = DownloadWindows.Evaluate(DownloadWindows.Parse(s.DownloadWindows), time.GetLocalNow()).Open,
        ["categories"] = config.Categories,
        ["pathRules"] = config.PathRules,
        ["pathWarnings"] = PathWarnings(config),
        ["hasExternal"] = config.ExternalClientType is not null,
        // Every download is kept; the field stays so older pages keep reading a valid value.
        ["defaultRetentionPolicy"] = "KEPT",
        ["defaultRetentionPolicyPersisted"] = !string.IsNullOrEmpty(s.DefaultRetentionPolicy),
        ["storageUsage"] = await StorageUsageAsync(config, ct),
    };
}

private int DefaultMaxActive() =>
    Math.Clamp(engineOptions.CurrentValue.MaxActiveDownloads, DownloadLimits.MinActiveDownloads, DownloadLimits.MaxActiveDownloads);

private static List<object> PathWarnings(ClientConfig config)
{
    var list = new List<object>();
    static string Normalize(string path) => path.Trim().Trim('"', '\'').Replace('\\', '/').TrimEnd('/').ToLowerInvariant();
    var current = new DirectoryInfo(Directory.GetCurrentDirectory());
    while (current.Parent is not null && !System.IO.File.Exists(Path.Combine(current.FullName, "TorrentFlow.slnx"))) current = current.Parent;
    var repo = Normalize(System.IO.File.Exists(Path.Combine(current.FullName, "TorrentFlow.slnx"))
        ? current.FullName : Directory.GetCurrentDirectory());
    var temporary = Normalize(Path.GetTempPath());
    void Check(string field, string? path, string? category = null)
    {
        if (string.IsNullOrWhiteSpace(path)) return;
        var normalized = Normalize(path);
        var segments = normalized.Split('/', StringSplitOptions.RemoveEmptyEntries);
        var reasons = new List<string>();
        if (segments.Any(s => System.Text.RegularExpressions.Regex.IsMatch(s, @"(?:^|[._-])e2e(?:$|[._-])|^(?:\.?playwright(?:[-_.].*)?|test-results?|playwright-report)$")))
            reasons.Add("test-directory");
        if (segments.Contains("node_modules")) reasons.Add("dependencies");
        if (segments.Any(s => s is "tmp" or ".tmp" or "temp" or ".temp") || normalized == temporary || normalized.StartsWith(temporary + '/', StringComparison.Ordinal))
            reasons.Add("temporary-directory");
        if (normalized == repo || normalized.StartsWith(repo + '/', StringComparison.Ordinal)) reasons.Add("inside-repository");
        if (reasons.Count == 0) return;
        var detail = reasons.Contains("inside-repository") ? "It is inside the TorrentFlow project."
            : reasons.Contains("temporary-directory") ? "It is in a temporary directory."
            : reasons.Contains("dependencies") ? "It is inside node_modules." : "It looks like a test directory.";
        list.Add(new { field, category, path, reasons, message = $"{detail} Tests, updates, or cleanup tools may remove files stored there. Choose a permanent media folder; TorrentFlow will not move existing files automatically." });
    }
    Check("baseDownloadPath", config.BaseDownloadPath);
    Check("savePath", config.SavePath);
    foreach (var (cat, p) in config.PathRules) Check("pathRule", p, cat);
    return list;
}

private async Task<object?> StorageUsageAsync(ClientConfig config, CancellationToken ct)
{
    var rows = await db.EngineTorrents.AsNoTracking().Where(r => r.UserId == LocalUser.Id).ToListAsync(ct);
    return SettingsDiskInventory.Usage(config, rows, ct);
}

    [HttpPut]
    public async Task<IActionResult> Put(CancellationToken ct)
    {
        if (await JsonBody.ReadAsync(Request, ct) is not { } body) return JsonBody.InvalidJson();
        if (SettingsInput.Validate(body) is { } failure) return BadRequest(new { error = failure.Error, field = failure.Field });
        IActionResult Bad(string reason) => BadRequest(new { ok = false, error = reason, message = reason });
        if (!store.ExternalClientsEnabled && (body.Str("clientType") is "qbittorrent" or "transmission"
            || body.Str("externalClientType") is "qbittorrent" or "transmission"
            || (body.Bool("test") == true && body.Str("testTarget") == "external")))
            return Bad("External clients are disabled in this build. TorrentFlow uses the built-in downloader only.");

        var row = await store.EnsureAsync(db, ct);

        if (body.Bool("switchToBuiltin") == true)
        {
            if (string.IsNullOrEmpty(row.ExternalClientType) && row.ClientType is "qbittorrent" or "transmission")
                row.ExternalClientType = row.ClientType;
            row.ClientType = "builtin";
            row.UpdatedAt = DateTime.UtcNow;
            await db.SaveChangesAsync(ct);
            return Ok(new
            {
                settings = await PublicSettingsAsync(row, ct),
                message = "Switched to built-in engine. External client kept for optional Send to my client.",
            });
        }

        if (body.Str("clientType") is { } clientType)
        {
            row.ClientType = clientType.Trim();
        }
        if (body.Has("externalClientType"))
        {
            var ext = body.Str("externalClientType")?.Trim();
            row.ExternalClientType = ext is null or "" or "none" ? null : ext;
        }
        if (row.ClientType is "qbittorrent" or "transmission") row.ExternalClientType = row.ClientType;
        if (body.Str("host")?.Trim() is { Length: > 0 } host)
        {
            if (!Uri.TryCreate(host.Trim(), UriKind.Absolute, out var uri) || uri.Scheme is not ("http" or "https"))
                return Bad("host must be an http(s) URL");
            row.Host = host.TrimEnd('/');
        }
        if (body.Has("username")) row.Username = body.Str("username")?.Trim();
        if (body.Has("password") && body.IsNull("password")) row.Password = null;
        if (body.Str("password") is { Length: > 0 } password)
        {
            if (password.Length > 4096) return Bad("password is too long");
            row.Password = secrets.Encrypt(password);
        }

        foreach (var field in new[] { "category", "savePath", "baseDownloadPath" })
        {
            if (!body.Has(field)) continue;
            var value = body.Str(field);
            if (value?.Contains('\0') == true) return Bad($"{field} contains an invalid null character");
            value = NullIfBlank(value);
            if (field == "category") row.Category = value;
            else if (field == "savePath") row.SavePath = value;
            else row.BaseDownloadPath = value;
        }

        var hasGb = body.Has("maxStorageGb");
        var hasBytes = body.Has("maxStorageBytes");
        if (hasGb && hasBytes) return BadRequest(new { error = "Provide maxStorageGb or maxStorageBytes, not both" });
        if (hasGb || hasBytes)
        {
            var field = hasGb ? "maxStorageGb" : "maxStorageBytes";
            if (body.IsNull(field) || body.Str(field) == "")
            {
                row.MaxStorageBytes = null;
                row.StorageCapConfigured = false;
            }
            else
            {
                var n = body.Num(field) ?? (double.TryParse(body.Str(field), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var p) ? p : double.NaN);
                if (!double.IsFinite(n) || n < 0) return Bad($"{field} must be a non-negative number");
                var bytes = hasGb ? Math.Round(n * 1e9) : n;
                if (!hasGb && bytes != Math.Floor(bytes)) return Bad("maxStorageBytes must be an integer");
                if (bytes > long.MaxValue) return Bad($"{field} is too large");
                row.MaxStorageBytes = bytes > 0 ? (long)bytes : null;
                row.StorageCapConfigured = bytes > 0;
            }
            storage.ResetDirectorySizeCache();
        }

        if (body.Bool("verboseDiagnostics") is { } verbose) row.VerboseDiagnostics = verbose;
        if (body.Has("preferredResolution"))
        {
            var r = body.Num("preferredResolution") ?? SettingsDefaults.Resolution;
            row.PreferredResolution = (int)r;
        }
        if (body.Has("automationIntervalMinutes"))
        {
            var m = body.Num("automationIntervalMinutes") ?? 0;
            row.AutomationIntervalMinutes = (int)m;
        }
        // auto, english or any (docs/release-language.md); auto is stored as null.
        if (body.Has("audioLanguage"))
        {
            var preference = body.IsNull("audioLanguage") ? null : ReleaseLanguage.NormalizePreference(body.Str("audioLanguage"));
            row.AudioLanguage = preference is null or ReleaseLanguage.Auto ? null : preference;
        }
        var capChanged = false;
        if (body.Has("maxActiveDownloads"))
        {
            // Null clears the saved value, falling back to the configured default.
            row.MaxActiveDownloads = body.IsNull("maxActiveDownloads") ? null : (int)body.Num("maxActiveDownloads")!.Value;
            capChanged = true;
        }
        List<DownloadWindow>? windows = null;
        if (body.TryGetProperty("downloadWindows", out var windowsJson))
        {
            // Validated up front; null or [] clears the schedule so downloads may start at any time again.
            if (windowsJson.ValueKind == JsonValueKind.Null) windows = [];
            else if (SettingsInput.ParseWindows(windowsJson, out windows) is { } windowError) return Bad(windowError);
            row.DownloadWindows = DownloadWindows.Serialize(windows);
        }
        if (body.TryGetProperty("categories", out var cats) && cats.ValueKind != JsonValueKind.Null)
        {
            if (cats.ValueKind != JsonValueKind.Array) return Bad("categories must be an array");
            var list = cats.EnumerateArray().Select(c => c.GetString()!.Trim()).ToList();
            if (list.Count > 64) return Bad("At most 64 categories");
            row.Categories = JsonSerializer.Serialize(list);
        }
        if (body.TryGetProperty("pathRules", out var rules) && rules.ValueKind != JsonValueKind.Null)
        {
            if (rules.ValueKind == JsonValueKind.Null) row.PathRules = null;
            else if (rules.ValueKind != JsonValueKind.Object) return Bad("pathRules must be an object");
            else
            {
                var map = new Dictionary<string, string>();
                foreach (var p in rules.EnumerateObject())
                {
                    if (p.Value.ValueKind != JsonValueKind.String) continue;
                    var path = p.Value.GetString()!.Trim();
                    if (path.Contains('\0')) return Bad("pathRules contains an invalid null character");
                    if (path.Length > 0) map[p.Name.Trim()] = path;
                }
                if (map.Count > 64) return Bad("At most 64 path rules");
                row.PathRules = map.Count > 0 ? JsonSerializer.Serialize(map) : null;
            }
        }
        if (body.Has("defaultRetentionPolicy"))
            row.DefaultRetentionPolicy = "KEPT";

        storage.ResetDirectorySizeCache();
        row.UpdatedAt = DateTime.UtcNow;
        await db.SaveChangesAsync(ct);
        // After the save, so a restart reads the same cap the running queue now uses.
        if (capChanged) limits.SetMaxActive(row.MaxActiveDownloads);
        if (windows is not null) limits.SetWindows(windows);

        object? testResult = null;
        if (body.Bool("test") == true)
        {
            var config = await clients.GetConfigAsync(ct);
            var type = body.Str("testTarget") == "external" && config.ExternalClientType is { } external && !string.IsNullOrWhiteSpace(config.Host)
                ? external : config.ClientType;
            testResult = type == "builtin"
                ? new EngineActionResult(true, "Built-in engine is running.")
                : await clients.Get(type).TestAsync(config with { ClientType = type }, ct);
        }

        return Ok(new Dictionary<string, object?>
        {
            ["settings"] = await PublicSettingsAsync(row, ct),
            ["testResult"] = testResult,
            ["retentionWarning"] = null,
        });
    }

    private static string? NullIfBlank(string? s) => string.IsNullOrWhiteSpace(s) ? null : s.Trim();
}

    [HttpPost]
    public async Task<IActionResult> Send(CancellationToken ct)
    {
        if (await JsonBody.ReadAsync(Request, ct) is not { } body) return JsonBody.InvalidJson();

        foreach (var (field, max) in StringLimits)
        {
            if (!body.IsKind(field, JsonValueKind.String, JsonValueKind.Null)) return Invalid($"{field} must be a string", field);
            if (body.Str(field) is { } v && v.Length > max) return Invalid($"{field} must be at most {max} characters", field);
        }
        foreach (var (field, allowed) in EnumFields)
        {
            if (!body.IsKind(field, JsonValueKind.String, JsonValueKind.Null)) return Invalid($"{field} must be a string", field);
            if (body.Str(field) is { } v && !allowed.Contains(v)) return Invalid($"{field} must be one of: {string.Join(", ", allowed)}", field);
        }

        var magnet = body.Str("magnet")?.Trim();
        var torrentUrl = body.Str("torrentUrl")?.Trim();
        var infoHashRaw = body.Str("infoHash")?.Trim();
        var retention = body.Str("retention");
        var scope = body.Str("scope");
        var target = body.Str("target") ?? "primary";
        var savePathOverride = body.Str("savePath");

        if (!string.IsNullOrEmpty(magnet) && TorrentSource.HashFromMagnet(magnet) is null)
            return Invalid("magnet must contain a valid BitTorrent info hash", "magnet");
        string? infoHash = null;
        if (!string.IsNullOrEmpty(infoHashRaw))
        {
            infoHash = TorrentSource.NormalizeInfoHash(infoHashRaw);
            if (infoHash is null) return Invalid("infoHash must be a 40-character hex or 32-character base32 hash", "infoHash");
        }
        if (!string.IsNullOrEmpty(torrentUrl))
        {
            if (!Uri.TryCreate(torrentUrl, UriKind.Absolute, out var uri)) return Invalid("torrentUrl must be a valid URL", "torrentUrl");
            if (uri.Scheme is not ("http" or "https")) return Invalid("torrentUrl must use http or https", "torrentUrl");
        }
        if (savePathOverride is not null && (savePathOverride.Contains('\0')
            || savePathOverride.Replace('\\', '/').Split('/').Any(seg => seg == "..")))
            return Invalid("savePath may not contain null bytes or traversal segments", "savePath");

        var config = await settings.GetConfigAsync(ct);
        if (target == "external" || config.ClientType != "builtin")
        {
            if ((config.ExternalClientType is null || string.IsNullOrWhiteSpace(config.Host)) && target == "external")
                return BadRequest(new { ok = false, offline = false, error = "No external client", message = "Configure an external torrent client in Settings first." });
            return await SendExternalAsync(body, target, magnet, torrentUrl, infoHash, retention, ct);
        }

        var hasSource = !string.IsNullOrEmpty(magnet) || !string.IsNullOrEmpty(torrentUrl);
        if (!hasSource && infoHash is not null && retention is "keep" or "stream")
        {
            if (scope is "episode" or "season")
                return BadRequest(new { ok = false, message = "Episode and season acquisitions must use their scoped title endpoint." });
            return await RetentionOnlyAsync(infoHash, ct);
        }
        if (!hasSource) return Invalid("magnet or torrentUrl is required (or infoHash with retention)", "magnet");

        var resolved = await SmartTargetAsync(body, config, ct);
        var overrideCap = body.Bool("overrideStorageCap") ?? false;
        var expected = body.Num("expectedSizeBytes") is { } n && n > 0 ? (long)n : (long?)null;
        var targetJson = new { category = resolved.Category, savePath = resolved.SavePath };

        var check = storage.Check(config.DownloadRoot, config.MaxStorageBytes, expected, await engine.QueuedReservedBytesAsync(ct), overrideCap);
        if (!check.Ok)
            return StatusCode(507, new
            {
                ok = false, offline = false, error = "Storage limit", message = check.Message, clientType = "builtin", target = targetJson,
                storage = new
                {
                    limit = check.Limit, overridable = check.Overridable, usedBytes = check.UsedBytes, freeBytes = check.FreeBytes,
                    maxStorageBytes = check.MaxStorageBytes, incomingBytes = check.IncomingBytes, incomingEstimated = check.IncomingEstimated,
                    reservedQueuedBytes = check.ReservedQueuedBytes,
                },
            });

        var result = await engine.AddAsync(new EngineAddRequest
        {
            Magnet = magnet,
            TorrentUrl = torrentUrl,
            InfoHash = infoHash,
            Name = body.Str("name"),
            Purpose = TorrentPurpose.Keep,
            Category = resolved.Category,
            SavePath = resolved.SavePath,
            QueueKey = body.Str("queueKey"),
            WorkId = body.Str("workId"),
            ExpectedSizeBytes = expected,
            Forced = body.Bool("forced") ?? false,
            OverrideStorageCap = overrideCap,
            // A manual send is the owner's own pick unless the caller names another lane (requests).
            Lane = body.Str("lane") ?? TorrentLane.Owner,
            // The owner chose this release himself: it always goes.
            Provenance = EngineProvenance.Hand,
        }, ct);

        var smart = new { kind = resolved.Smart.Kind, category = resolved.Smart.Category, confidence = resolved.Smart.Confidence };
        if (!result.Ok && result.InvalidField is { } invalidField)
            return Invalid(result.Message, invalidField);
        if (!result.Ok)
            return StatusCode(502, new { ok = false, message = result.Message, offline = false, code = result.StorageLimit is null ? "SEND_FAILED" : "STORAGE_LIMIT",
                unusable = result.Unusable, clientType = "builtin", sendTarget = target, target = targetJson, smart });

        return Ok(new
        {
            ok = true, message = EngineAddMessages.Format(result), offline = false, clientType = "builtin", sendTarget = target, target = targetJson, smart,
            retentionState = "kept",
            hash = result.Hash, details = result.Details,
        });
    }

    private async Task<IActionResult> SendExternalAsync(JsonElement body, string target, string? magnet, string? torrentUrl,
        string? infoHash, string? retention, CancellationToken ct)
    {
        var config = await clients.GetConfigAsync(ct);
        if (target == "external") config = config with { ClientType = config.ExternalClientType! };
        if (string.IsNullOrEmpty(magnet) && string.IsNullOrEmpty(torrentUrl))
        {
            if (infoHash is not null && retention is "keep" or "stream")
            {
                if (body.Str("scope") is "episode" or "season")
                    return BadRequest(new { ok = false, message = "Episode and season acquisitions must use their scoped title endpoint." });
                var existing = await db.EngineTorrents.AsNoTracking().FirstOrDefaultAsync(t => t.UserId == LocalUser.Id && t.Hash == infoHash, ct);
                var state = existing?.Origin == TorrentOrigin.User ? "kept" : "unknown";
                return Ok(new { ok = true, message = "Kept in your library.", clientType = config.ClientType, sendTarget = target, retentionState = state });
            }
            return Invalid("magnet or torrentUrl is required (or infoHash with retention)", "magnet");
        }
        var resolved = await SmartTargetAsync(body, config, ct);
        var hash = infoHash ?? (magnet is null ? null : TorrentSource.HashFromMagnet(magnet));
        var existingTransfer = hash is null ? null : await db.EngineTorrents.AsNoTracking()
            .FirstOrDefaultAsync(t => t.UserId == LocalUser.Id && t.Hash.ToLower() == hash, ct);
        var watchId = body.Str("watchListItemId");
        var watch = string.IsNullOrEmpty(watchId) ? null : await db.WatchListItems.AsNoTracking()
            .FirstOrDefaultAsync(t => t.UserId == LocalUser.Id && t.Id == watchId, ct);
        var history = new DownloadHistory
        {
            Id = Ids.New(), UserId = LocalUser.Id, CreatedAt = DateTime.UtcNow, Title = body.Str("name") ?? "Unknown",
            Magnet = magnet, TorrentUrl = torrentUrl, InfoHash = infoHash, Source = body.Str("source"),
            WorkId = watch?.WorkId ?? existingTransfer?.WorkId, Retention = "keep", Status = "failed",
        };
        var check = storage.Check(config.DownloadRoot ?? resolved.SavePath, config.MaxStorageBytes, null,
            await engine.QueuedReservedBytesAsync(ct), body.Bool("overrideStorageCap") ?? false);
        if (!check.Ok)
        {
            history.Message = check.Message;
            db.DownloadHistories.Add(history);
            await db.SaveChangesAsync(ct);
            return StatusCode(507, new
            {
                ok = false, offline = false, error = "Storage limit", message = check.Message, clientType = config.ClientType,
                target = new Dictionary<string, object?> { ["category"] = resolved.Category, ["savePath"] = resolved.SavePath },
                storage = new
                {
                    limit = check.Limit, overridable = check.Overridable, usedBytes = check.UsedBytes, freeBytes = check.FreeBytes,
                    maxStorageBytes = check.MaxStorageBytes, incomingBytes = check.IncomingBytes, incomingEstimated = check.IncomingEstimated,
                    reservedQueuedBytes = check.ReservedQueuedBytes,
                },
            });
        }
        var result = await clients.Get(config.ClientType).AddAsync(config, new EngineAddRequest
        {
            Magnet = magnet, TorrentUrl = torrentUrl, Name = body.Str("name"), Purpose = TorrentPurpose.Keep,
            Category = resolved.Category, SavePath = resolved.SavePath,
        }, ct);
        history.Status = result.Ok ? "sent" : "failed";
        history.Message = result.Message;
        history.Category = resolved.Category;
        history.SavePath = resolved.SavePath;
        history.ClientType = config.ClientType;
        history.SendKind = resolved.Kind;
        db.DownloadHistories.Add(history);
        await db.SaveChangesAsync(ct);
        if (result.Ok) storage.ResetDirectorySizeCache();
        var offline = !result.Ok && ExternalClientErrors.IsOffline(result.Message);
        return StatusCode(result.Ok ? 200 : offline ? 503 : 502, new
        {
            ok = result.Ok, message = result.Message, offline, clientType = config.ClientType, sendTarget = target,
            target = new Dictionary<string, object?> { ["category"] = resolved.Category, ["savePath"] = resolved.SavePath },
            smart = new { kind = resolved.Smart.Kind, category = resolved.Smart.Category, confidence = resolved.Smart.Confidence },
            retentionState = "kept",
        });
    }

    /// <summary>resolveSmartSendTarget over the body hints; a watchlist grab supplies the catalog's own metadata.</summary>
    private async Task<SmartSendTarget> SmartTargetAsync(JsonElement body, ClientConfig config, CancellationToken ct)
    {
        MediaMetadata? metadata = null;
        if (body.TryGetProperty("metadata", out var meta) && meta.ValueKind == JsonValueKind.Object)
        {
            try { metadata = meta.Deserialize<MediaMetadata>(JsonSerializerOptions.Web); }
            catch (JsonException) { metadata = null; }
        }
        if (metadata is null && body.Str("watchListItemId") is { Length: > 0 } watchId
            && await db.WatchListItems.AsNoTracking().FirstOrDefaultAsync(w => w.UserId == LocalUser.Id && w.Id == watchId, ct) is { } watch)
            metadata = CatalogMetadata(watch.MediaType, watch.ExternalId, watch.Title);
        string[]? tags = body.TryGetProperty("tags", out var t) && t.ValueKind == JsonValueKind.Array
            ? [.. t.EnumerateArray().Where(x => x.ValueKind == JsonValueKind.String).Select(x => x.GetString()!)]
            : null;
        return SmartSendTargets.Resolve(config, HttpContext.RequestServices.GetService<ISmartCategorizer>(), new SmartSendOptions
        {
            Name = body.Str("name"), Tags = tags, Metadata = metadata, Source = body.Str("source"),
            SearchCategory = body.Str("searchCategory"), CategoryManual = body.Bool("categoryManual") == true,
            Category = body.Str("category"), SavePath = body.Str("savePath"),
        });
    }

    /// <summary>catalogMetadata (catalog-identity.ts): only a known media type with a title identifies a work.</summary>
    private static MediaMetadata? CatalogMetadata(string? mediaType, string? externalId, string? title)
    {
        var type = (mediaType ?? "").Trim().ToLowerInvariant();
        var name = (title ?? "").Trim();
        if (type is not ("anime" or "movie" or "tv") || name.Length == 0) return null;
        return new MediaMetadata { Source = type == "anime" ? "anilist" : "tmdb", MediaType = type, ExternalId = (externalId ?? "").Trim(), Title = name };
    }

    /// <summary>Marks an existing transfer as kept, never adding anything. Every download is kept, so this only
    /// confirms it to older pages that still ask.</summary>
    private async Task<IActionResult> RetentionOnlyAsync(string hash, CancellationToken ct)
    {
        var row = await db.EngineTorrents.FirstOrDefaultAsync(r => r.UserId == LocalUser.Id && r.Hash == hash, ct);
        if (row is not null && row.Origin != TorrentOrigin.User)
        {
            row.Origin = TorrentOrigin.User;
            row.UpdatedAt = DateTime.UtcNow;
            await db.SaveChangesAsync(ct);
        }
        return Ok(new
        {
            ok = true,
            message = "Kept in your library.",
            clientType = "builtin",
            sendTarget = "primary",
            retentionState = "kept",
        });
    }
}

