[HttpGet]
public async Task<IActionResult> Get(string workKey, [FromQuery] string? t, [FromQuery] int? y,
    [FromQuery] string? type, [FromQuery] int? s, [FromQuery] int? remembered, CancellationToken ct)
{
    var provider = Request.Query["provider"].ToString().Trim().ToLowerInvariant();
    var external = Request.Query["providerId"].ToString();
    if (external.Length == 0) external = Request.Query["externalId"].ToString();
    MediaMetadata? resolved = null;
    if (provider.Length > 0 && !IMetadataResolver.SupportsProvider(provider)) return BadRequest(new { error = "Unsupported title provider" });
    if (external.Length > 0)
    {
        if (!IMetadataResolver.SupportsProvider(provider)) return BadRequest(new { error = "A supported title provider is required." });
        resolved = await metadata.GetByIdAsync(provider, type == "movie" ? "movie" : "tv", external, ct);
        if (resolved != null && !TitleIdentity.Matches(workKey, resolved, await StoredIdsAsync(workKey, resolved, ct)))
            return BadRequest(new { error = "Provider identity does not match this title." });
    }
    await RefreshNamesAsync(workKey, resolved, ct);
    return Ok(await titles.Detail(new(workKey, t, y, type, s, remembered, resolved, TitleIdentity.From(provider, external), FindIdentity: true), ct));
}

/// <summary>The ids of the work stored at the key, when it is the record's kind (a record sharing one is that work).</summary>
private async Task<IReadOnlySet<string>?> StoredIdsAsync(string workKey, MediaMetadata record, CancellationToken ct)
{
    await using var db = await factory.CreateDbContextAsync(ct);
    var key = workKey.Trim().ToLowerInvariant();
    var work = await db.Works.AsNoTracking().Include(x => x.Links).FirstOrDefaultAsync(x => x.WorkKey == key, ct);
    return work != null && TorrentFlow.Core.Scheduling.HuntCursor.IsSeries(work.MediaType) == TitleIdentity.IsSeries(record) ? WorkIdentities.Of(work) : null;
}

/// <summary>
/// Opening a title saves its provider record's names, or looks a stale work's names up again, then links the work
/// to its other records if it never was (all within one budget; what runs out of time is finished by a later open).
/// </summary>
private async Task RefreshNamesAsync(string workKey, MediaMetadata? resolved, CancellationToken ct)
{
    using var budget = CancellationTokenSource.CreateLinkedTokenSource(ct);
    budget.CancelAfter(TimeSpan.FromMilliseconds(2500));
    var key = workKey.Trim().ToLowerInvariant();
    try
    {
        await names.RefreshAsync(key, resolved, fetch: true, budget.Token);
        if (linker != null) await linker.LinkAsync(key, budget.Token);
    }
    catch (OperationCanceledException) when (!ct.IsCancellationRequested) { }
    catch (Exception error) when (!ct.IsCancellationRequested)
    {
        // The page opens with what is stored; a later open or the backfill finishes the names and links.
        logger?.LogWarning("Refreshing the names and links of {WorkKey} failed: {Error}", key, error.InnerException?.Message ?? error.Message);
    }
}

/// <summary>The work's crosswalk: each record at another provider it is linked to, and where the link came from.</summary>

[HttpGet("links")]
public async Task<IActionResult> Links(string workKey, CancellationToken ct)
{
    if (linker == null) return NotFound(new { error = "Links are not available." });
    var links = await linker.ListAsync(workKey.Trim().ToLowerInvariant(), ct);
    return links == null ? NotFound(new { error = "This title has no saved record yet." }) : Ok(new { links });
}

/// <summary>The owner unlinks a record: it is never linked again, and its ids and names leave the work.</summary>

[HttpDelete("links/{provider}/{externalId}")]
public async Task<IActionResult> Unlink(string workKey, string provider, string externalId, CancellationToken ct)
{
    if (linker == null) return NotFound(new { error = "Links are not available." });
    var removed = await linker.UnlinkAsync(workKey.Trim().ToLowerInvariant(), provider.Trim().ToLowerInvariant(), externalId.Trim(), ct);
    if (!removed) return NotFound(new { ok = false, message = "That link was not found. Reload the page and try again." });
    return Ok(new { ok = true, links = await linker.ListAsync(workKey.Trim().ToLowerInvariant(), ct) });
}

[HttpPost]
public async Task<IActionResult> Post(string workKey, CancellationToken ct)
{
    var f = await Fields.Read(Request, ct);
    var scope = f.String("scope");
    int? Positive(string name) => f.Raw(name).ValueKind == JsonValueKind.Number && f.Raw(name).TryGetInt32(out var n) && n > 0 ? n : null;
    var season = Positive("season");
    var episode = Positive("episode");
    var episodesRaw = f.Raw("episodes");
    var episodes = episodesRaw.ValueKind == JsonValueKind.Array ? episodesRaw.EnumerateArray()
        .Where(x => x.ValueKind == JsonValueKind.Number && x.TryGetInt32(out var n) && n > 0).Select(x => x.GetInt32()).Distinct().Order().Take(500).ToArray() : [];
    string? failure = !string.IsNullOrEmpty(f.String("infoHash")) ? "Acquisition intent cannot pin or promote a torrent hash." :
        scope switch
        {
            "episode" when season == null || episode == null || episodes.Length > 0 => "Episode scope requires exactly one season and episode.",
            "season" when season == null || f.Raw("episode").ValueKind is not (JsonValueKind.Undefined or JsonValueKind.Null) => "Season scope requires a season.",
            "title" when f.Raw("season").ValueKind is not (JsonValueKind.Undefined or JsonValueKind.Null) ||
                f.Raw("episode").ValueKind is not (JsonValueKind.Undefined or JsonValueKind.Null) || episodes.Length > 0 => "Title scope cannot include season or episode coordinates.",
            not ("episode" or "season" or "title") => "An explicit acquisition scope is required.",
            _ => null
        };
    if (failure != null) return BadRequest(new { ok = false, message = failure });
    var resolution = Positive("preferredResolution");
    if (f.Raw("preferredResolution").ValueKind is not (JsonValueKind.Undefined or JsonValueKind.Null) &&
        (resolution == null || !new[] { 480, 720, 1080, 2160 }.Contains(resolution.Value)))
        return BadRequest(new { ok = false, message = "Preferred resolution must be 480p, 720p, 1080p, or 2160p." });
    // Every download is kept; older pages may still send "stream", which is accepted and treated as keep.
    f.Enum("retention", ["keep", "stream"]);
    var cap = f.Bool("overrideStorageCap") == true;
    // Provider IDs are authoritative claims even when optional display hints are absent.
    string? Claim(string name) => f.Raw(name) is { ValueKind: JsonValueKind.String } v && v.GetString()!.Trim() is { Length: > 0 and <= 200 } s ? s : null;
    var claimedProvider = Claim("provider")?.ToLowerInvariant();
    var externalId = Claim("providerId");
    var sourceType = (Claim("sourceType") ?? Claim("mediaType"))?.ToLowerInvariant();
    MediaMetadata? verified = null;
    if (externalId != null)
    {
        if (claimedProvider == null || !IMetadataResolver.SupportsProvider(claimedProvider))
            return BadRequest(new { ok = false, message = "A supported title provider is required." });
        verified = await metadata.GetByIdAsync(claimedProvider, sourceType == "movie" ? "movie" : "tv", externalId, ct);
        if (verified == null || !TitleIdentity.Matches(workKey, verified, await StoredIdsAsync(workKey, verified, ct)))
            return BadRequest(new { ok = false, message = "Provider identity does not match this title." });
    }
    var detail = await titles.Detail(new(workKey, f.String("title", nullable: true), (int?)f.Number("year", nullable: true), f.String("mediaType", nullable: true), Provider: verified), ct);
    var title = (string)detail["title"]!;
    var type = detail["mediaType"] as string ?? ((bool)detail["isSeries"]! ? "tv" : "movie");
    if (scope == "title" && (bool)detail["isSeries"]!)
        return Conflict(new { ok = false, message = "Choose an episode or season to download first." });
    var library = (Dictionary<string, object?>)detail["library"]!;
    var watchId = library["watchListItemId"] as string;
    // The page's own catalog identity (an AniList film from a home rail, say) belongs on the work even when the click
    // carried no provider claim: the grab decides anime from it, and the Downloaded card draws its poster from it.
    var provider = verified?.Source ?? (detail.GetValueOrDefault("provider") as string is { } known && IMetadataResolver.SupportsProvider(known) ? known : null);
    var providerId = verified?.ExternalId ?? (provider == null ? null : detail.GetValueOrDefault("providerId") as string);
    if (providerId == null) provider = null;
    await using var db = await factory.CreateDbContextAsync(ct);
    var isSeries = TorrentFlow.Core.Scheduling.HuntCursor.IsSeries(type);
    // Everything this click says the title is: the verified record's own id, canonical ids, or the page's identity.
    var claim = verified != null ? WorkIdentities.Of(verified.Ids, verified.Source, verified.ExternalId) : WorkIdentities.Of(null, provider, providerId);
    // The same test search keys cards by: a stored work is the claimed title when it shares an id with it (its provider
    // id, canonical ids or verified links), and may take it when it is the same kind and no id of it contradicts it.
    bool Is(Work w) => TorrentFlow.Core.Scheduling.HuntCursor.IsSeries(w.MediaType) == isSeries &&
        claim.Count > 0 && WorkIdentities.Compare(WorkIdentities.Of(w), claim) == IdentityMatch.Same;
    bool Fits(Work w) => TorrentFlow.Core.Scheduling.HuntCursor.IsSeries(w.MediaType) == isSeries &&
        (claim.Count == 0 || WorkIdentities.Compare(WorkIdentities.Of(w), claim) != IdentityMatch.Different);
    var work = await db.Works.Include(x => x.Links).FirstOrDefaultAsync(x => x.WorkKey == workKey, ct);
    if (work == null || !Is(work))
    {
        // The claimed record may already be stored under another key (this key's namesake, a key from before search
        // dated namesakes, or another catalog's record whose ids or verified links name it): the download belongs to
        // that work, never to a second copy of it or to the key's other title.
        Work? identified = null;
        var external = claim.Select(WorkIdentities.Value).ToList();
        if (external.Count > 0)
        {
            var matches = await db.Works.Include(x => x.Links)
                .Where(x => (x.ProviderId != null && external.Contains(x.ProviderId)) ||
                    x.Links.Any(l => l.Verified && !l.Rejected && external.Contains(l.ExternalId)))
                .ToListAsync(ct);
            // Canonical ids are matched as the exact text they take in IdsJson ("tmdb":21 never finds 210 or 2134).
            foreach (var token in claim.SelectMany(WorkIdentities.JsonTokens))
                matches.AddRange(await db.Works.Include(x => x.Links).Where(x => x.IdsJson.Contains(token)).ToListAsync(ct));
            // The claimed record's own work first, then one whose canonical ids share an id before one only a link names,
            // then the nearest year (an anime and its sequel can both be linked to one IMDb id).
            var year = verified?.Year ?? detail["year"] as int?;
            identified = matches.Where(Is).DistinctBy(x => x.Id)
                .OrderByDescending(x => x.Provider == provider && x.ProviderId == providerId)
                .ThenByDescending(x => WorkIdentities.Of(x.ReadIds(), x.Provider, x.ProviderId).Overlaps(claim))
                .ThenBy(x => x.Year is { } a && year is { } b ? Math.Abs(a - b) : 99)
                .FirstOrDefault();
        }
        if (identified != null)
        {
            work = identified;
            workKey = identified.WorkKey;
        }
        else if (work != null && !Fits(work))
        {
            // The key's work is another title (the other kind, or a record whose id contradicts the claim): the first
            // key no other work holds, base or kind-tagged, as search assigns it ("the-flash-2023-tv", then
            // "the-flash-2023-tv-tmdb200").
            work = null;
            var free = false;
            foreach (var candidate in TorrentFlow.Core.Text.WorkKeySlug.KeyCandidates(workKey, isSeries, provider, providerId))
            {
                var holder = await db.Works.Include(x => x.Links).FirstOrDefaultAsync(x => x.WorkKey == candidate, ct);
                if (holder != null && !Fits(holder)) continue;
                (work, workKey, free) = (holder, candidate, true);
                break;
            }
            if (!free)
                return Conflict(new { ok = false, message = "Another title already uses this page. Open it from search and try again." });
        }
    }
    // An identity is unique to one work; a page-derived identity already held by another work key is not copied here.
    if (verified == null && provider != null && await db.Works.AnyAsync(x => x.Provider == provider && x.ProviderId == providerId && x.MediaType == type && x.WorkKey != workKey, ct))
        provider = providerId = null;
    if (work == null)
    {
        var workNames = verified != null ? WorkNames.Of(verified) : WorkNames.Legacy(title, detail["aliases"] as string[], provider);
        work = new() { Id = Ids.New(), WorkKey = workKey, CanonicalTitle = title, MediaType = type, Year = detail["year"] as int?,
            PosterUrl = detail["posterUrl"] as string, NamesJson = workNames.ToJson(),
            IdsJson = (verified?.Ids ?? new()).Merge(WorkIds.From(provider, providerId)).ToJson() ?? "{}",
            Format = WorkFormats.Of(verified) ?? WorkFormats.FromMediaType(type), OriginalLanguage = WorkFormats.LanguageOf(verified),
            Anime = verified != null ? AnimeIdentity.IsAnime(verified) : null,
            Provider = provider, ProviderId = providerId, CreatedAt = DateTime.UtcNow, UpdatedAt = DateTime.UtcNow };
        db.Works.Add(work);
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException error) when (IsUniqueViolation(error))
        {
            db.Entry(work).State = EntityState.Detached;
            work = await db.Works.FirstOrDefaultAsync(x => x.WorkKey == workKey, ct)
                ?? await db.Works.SingleAsync(x => x.Provider == provider && x.ProviderId == providerId && x.MediaType == type, ct);
            workKey = work.WorkKey;
        }
    }
    else if (provider != null && work.ProviderId == null)
    {
        work.Provider = provider;
        work.ProviderId = providerId;
        work.PosterUrl ??= detail["posterUrl"] as string;
        work.UpdatedAt = DateTime.UtcNow;
        await db.SaveChangesAsync(ct);
    }
    // A verified provider record's names belong on the work, whether it was just created or already known.
    if (verified != null) await names.RefreshAsync(workKey, verified, fetch: false, ct);
    // A legacy unlinked row on the page joins this work only when it was saved from a page or with an id of this work or
    // of the record the download claims (TitleService.SavedFor): a row saved from another record stays as it was.
    if (watchId != null && await db.WatchListItems.AsNoTracking().FirstOrDefaultAsync(x => x.Id == watchId && x.UserId == LocalUser.Id && x.WorkId == null, ct) is { } row
        && (row.ExternalId.Contains(':') || TitleService.SavedFor(row, WorkIdentities.Of(work).Concat(claim).ToHashSet(StringComparer.OrdinalIgnoreCase), workKey)))
        await db.WatchListItems.Where(x => x.Id == watchId && x.UserId == LocalUser.Id && x.WorkId == null)
            .ExecuteUpdateAsync(x => x.SetProperty(w => w.WorkId, work.Id), ct);
    await db.CatalogEntries.Where(x => x.WorkKey == workKey).ExecuteUpdateAsync(x => x.SetProperty(c => c.WorkId, work.Id), ct);
    if (scope == "season")
    {
        // The server decides which episodes a season has; a list the browser rendered is never trusted.
        var shape = await seasonShapes.GetSeasonAsync(new(workKey, title, work.Year, work.MediaType, verified?.Source ?? work.Provider,
            verified?.ExternalId ?? work.ProviderId, season!.Value), ct);
        episodes = shape?.AiredEpisodes.Take(500).ToArray() ?? [];
        if (episodes.Length == 0)
            return Conflict(new { ok = false, message = shape is null or { Provisional: true, Episodes.Count: 0 }
                ? "We couldn't load this season's episode list right now. Try again in a minute."
                : $"No episodes of season {season} have aired yet." });
    }
    // Every download is fire and forget: record what is wanted and return. The wanted queue runs the shared grab in
    // the background (the film grab, or the single-episode grab for each episode) and keeps retrying whatever is not
    // found yet. A dead release costs the queue a metadata timeout, never the click. The answer names the work the
    // download went to, so a page that is another work's key ("doctor-who-2005" for "doctor-who-2005-tv") can follow it.
    if (scope == "season")
    {
        await wanted.EnqueueAsync(new(workKey, work.Id, season!.Value, episodes, resolution, cap, TorrentLane.Owner), CancellationToken.None);
        return Accepted(LibraryJson.Object(("ok", true), ("queued", true), ("message", $"Season {season} queued."), ("workKey", workKey),
            ("report", new { season, totalEpisodes = episodes.Length, coveredEpisodes = 0, strategy = "unknown", coverageConfirmed = false,
                episodes = episodes.Select(e => new { episode = e, status = "not_measured" }),
                planReason = "We'll get each episode and keep looking for any we can't find yet." })));
    }
    await wanted.EnqueueAsync(new(workKey, work.Id, season, episode is { } one ? [one] : [], resolution, cap, TorrentLane.Owner, Single: true),
        CancellationToken.None);
    return Accepted(LibraryJson.Object(("ok", true), ("queued", true), ("workKey", workKey),
        ("message", episode is { } clicked ? $"Looking for episode {clicked}." : $"Looking for {title}.")));
}

private static EpisodeTransfer Transfer(GrabResult result, int? episode) => new(episode ?? 0,
    result.Ok ? result.Queued ? "queued" : "downloading" : "failed", result.Ok ? result.InfoHash : null, result.Ok ? null : result.Message);

/// <summary>"Pick a release yourself": a manual search for this title, episode or season, prefilled with our query.</summary>

[HttpGet("releases")]
public async Task<IActionResult> Releases(string workKey, [FromQuery] int? season, [FromQuery] int? episode, [FromQuery] string? q,
    CancellationToken ct) => Ok(await picker.Search(workKey, season is > 0 ? season : null, episode is > 0 ? episode : null, q, ct));

    [HttpPost("releases")]
    public async Task<IActionResult> PickRelease(string workKey, CancellationToken ct)
    {
        var f = await Fields.Read(Request, ct);
        var token = f.String("token");
        if (string.IsNullOrWhiteSpace(token)) return BadRequest(new { ok = false, message = "Choose a release first." });
        var result = await picker.Pick(workKey, token, null, lifetime.ApplicationStopping);
        if (result.Ok && result.InfoHash != null) await SettlePicked(workKey, result, CancellationToken.None);
        return StatusCode(result.Ok ? 200 : 409, LibraryJson.Object(("ok", result.Ok), ("message", result.Message),
            ("title", result.Title), ("infoHash", result.InfoHash), ("queued", result.Queued), ("storage", result.Storage)));
    }

    /// <summary>A hand-picked release settles the failed or queued target it covers: its episode, or the film.</summary>
    private async Task SettlePicked(string workKey, GrabResult result, CancellationToken ct)
    {
        await using var db = await factory.CreateDbContextAsync(ct);
        var row = await db.EngineTorrents.AsNoTracking().Where(t => t.UserId == LocalUser.Id && t.Hash == result.InfoHash)
            .Select(t => new { t.QueueKey, t.WorkId }).FirstOrDefaultAsync(ct);
        if (row?.WorkId == null) return;
        var key = TorrentFlow.Core.QueueKeys.Parse(row.QueueKey);
        var targets = db.AcquisitionTargets.AsNoTracking().Where(t => t.UserId == LocalUser.Id && t.WorkKey == workKey);
        targets = key is { } single ? targets.Where(t => t.Scope == "episode" && t.Season == single.Season && t.Episode == single.Episode)
            : targets.Where(t => t.Scope == "title");
        var tracked = await targets.ToDictionaryAsync(t => t.TargetKey, t => t.Episode, ct);
        if (tracked.Count == 0) return;
        await wanted.ClaimPickedAsync(workKey, key?.Season, tracked, row.WorkId, tracked.Values.Distinct().Select(ep => Transfer(result, ep)).ToArray(), ct);
    }

    private static bool IsUniqueViolation(DbUpdateException error) =>
        error.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 or 1555 };
}

[HttpGet]
public async Task<IActionResult> Get(CancellationToken ct)
{
    await using var db = await factory.CreateDbContextAsync(ct);
    var items = await db.WatchListItems.AsNoTracking().Include(x => x.Work).Where(x => x.UserId == LocalUser.Id).OrderByDescending(x => x.UpdatedAt).ToListAsync(ct);
    var posters = await WorkPosters.LoadAsync(db, items.Select(x => WorkPosters.KeyFor(x.Work?.WorkKey, x.Title)), ct);
    var resolved = items.Select(x => (x.Id, Stored: x.PosterUrl, Resolved: WorkPosters.Pick(posters, WorkPosters.KeyFor(x.Work?.WorkKey, x.Title), x.PosterUrl))).ToList();
    await WorkPosters.StoreOnWatchlistAsync(db, resolved, ct);
    foreach (var (item, art) in items.Zip(resolved)) item.PosterUrl = art.Resolved;
    var workIds = items.Where(x => x.WorkId != null).Select(x => x.WorkId!).ToList();
    // Ready = a download of the title promoted into the library (the one done-ness predicate) whose recorded files are
    // all still on disk (not removed, failed or moved away), so the card can say so.
    var ready = (await db.EngineTorrents.AsNoTracking().Where(t => t.UserId == LocalUser.Id && t.WorkId != null && workIds.Contains(t.WorkId)
            && t.Status != EngineTorrentStatus.Error && t.Status != EngineTorrentStatus.Removed).Where(EngineTorrent.Downloaded)
        .Select(t => new { WorkId = t.WorkId!, t.VerifiedFilesJson }).ToListAsync(ct))
        .Where(t => VerifiedFiles.StillOnDisk(t.VerifiedFilesJson) != false).Select(t => t.WorkId).ToHashSet();
    return Ok(new { items = items.Select(x => { var row = WithWorkKey(LibraryJson.Row(x), x.Work?.WorkKey); row["ready"] = x.WorkId != null && ready.Contains(x.WorkId); return row; }) });
}

/// <summary>A row with its linked work's key: the page it opens ("doctor-who-2005"), never one rebuilt from its title.</summary>
private static Dictionary<string, object?> WithWorkKey(Dictionary<string, object?> row, string? workKey)
{
    row["workKey"] = workKey;
    return row;
}

[HttpPost, HttpPatch]
public async Task<IActionResult> Save(CancellationToken ct)
{
    var f = await Fields.Read(Request, ct);
    var patch = HttpMethods.IsPatch(Request.Method);
    var id = patch ? f.String("id", true, 128) : null;
    var type = patch ? null : f.String("mediaType", true, 32)?.ToLowerInvariant();
    type = type switch { "movies" => "movie", "series" => "tv", _ => type };
    if (!patch && type is not ("anime" or "movie" or "tv")) Fields.Fail("mediaType must be anime, movie, or tv", "mediaType");
    var externalId = patch ? null : f.String("externalId", true, 128);
    var title = patch ? null : f.String("title", true);
    var poster = patch ? null : f.String("posterUrl", max: 2048, nullable: true);
    var synopsis = patch ? null : f.String("synopsis", max: 20000, nullable: true);
    var rating = patch ? null : f.Number("rating", max: 10, nullable: true);
    var workKey = patch ? null : f.String("workKey", max: 200, nullable: true);
    var provider = patch ? null : f.String("provider", max: 32, nullable: true);
    var providerId = patch ? null : f.String("providerId", max: 200, nullable: true);
    // The provider's own format (Movie, Series, Special, or AniList's MOVIE, TV...), a hint for when its record can't be read.
    var formatHint = patch ? null : f.String("format", max: 16, nullable: true);
    var status = f.Enum("status", ["watching", "planned", "completed", "dropped"]);
    var monitored = f.Bool("monitored");
    var fromSeason = f.Int("fromSeason", 10000);
    var fromEpisode = f.Int("fromEpisode");
    var cursorSeason = patch ? f.Int("cursorSeason", 10000) : null;
    var cursorEpisode = patch ? f.Int("cursorEpisode") : null;
    var lastEpisode = patch ? f.String("lastEpisode", max: 100, nullable: true) : null;
    var mode = f.Enum("monitorMode", [HuntCursor.OngoingMode, HuntCursor.NewEpisodesMode]);
    var resolution = f.Int("preferredResolution");
    if (resolution != null && !new[] { 480, 720, 1080, 2160 }.Contains(resolution.Value))
        Fields.Fail("preferredResolution must be one of 480, 720, 1080, 2160");
    // Two adds of the same new title at once both create its work or row; the loser of the unique index reads the
    // winner's and links to it on the next attempt, so every add succeeds against one work and one row.
    for (var attempt = 0; ; attempt++)
    {
        try { return await SaveOnce(); }
        catch (DbUpdateException error) when (!patch && IsUniqueViolation(error) && attempt < 6)
        {
            await Task.Delay(TimeSpan.FromMilliseconds(Random.Shared.Next(10, 60)), ct);
        }
    }

    async Task<IActionResult> SaveOnce()
    {
    await using var db = await factory.CreateDbContextAsync(ct);
    WorkChoice? choice = null;
    if (!patch)
    {
        choice = await WorkFor(db, workKey, provider, providerId ?? externalId, type!, externalId!, title!, poster, formatHint, ct);
        if (choice.Conflict != null) return Conflict(new { error = choice.Conflict });
    }
    // The row's type is the work's kind: an AniList film is a film the hunter grabs once, not a series.
    var rowType = choice?.RowType ?? type;
    // A row is its catalog's: TMDB movie 123 and AniList film 123 are two rows. An existing row is reused only when
    // it is this work's, has the same catalog and id, or is an unlinked row saved before rows named their catalog that
    // is this same title (LegacyRowAsync); it never keeps a different work.
    var rowProvider = choice?.Provider ?? "";
    var chosenId = choice?.Work?.Id;
    var item = patch
        ? await db.WatchListItems.FirstOrDefaultAsync(x => x.Id == id && x.UserId == LocalUser.Id, ct)
        : (chosenId != null ? await db.WatchListItems.FirstOrDefaultAsync(x => x.WorkId == chosenId && x.UserId == LocalUser.Id, ct) : null)
          ?? await db.WatchListItems.FirstOrDefaultAsync(x => x.UserId == LocalUser.Id && x.MediaType == rowType && x.ExternalId == externalId &&
              x.Provider == rowProvider, ct)
          ?? (rowProvider != "" ? await LegacyRowAsync(db, rowType!, externalId!, title!, ct) : null);
    if (!patch && rowProvider != "" && item is { Provider: "" } && item.MediaType == rowType && item.ExternalId == externalId) item.Provider = rowProvider;
    if (patch && item == null) return NotFound(new { error = "Not found" });
    var existed = item != null;
    if (!patch && string.IsNullOrEmpty(poster))
    {
        try
        {
            var art = await metadata.ResolveMetadataAsync(title!, type, ct);
            poster = art?.PosterUrl;
            synopsis ??= art?.Synopsis;
            rating ??= art?.Rating;
        }
        catch (Exception) when (!ct.IsCancellationRequested) { /* Artwork cannot block adding a title. */ }
    }
    var now = DateTime.UtcNow;
    var previousCursor = item == null ? null : EpisodeCursor.Resolve(item);
    var previousResolution = item?.PreferredResolution;
    if (item == null)
    {
        item = new WatchListItem { Id = Ids.New(), UserId = LocalUser.Id, Title = title!, MediaType = rowType!,
            ExternalId = externalId!, Provider = rowProvider, Status = status ?? "watching", Monitored = monitored ?? true,
            MonitorMode = HuntCursor.OngoingMode, CreatedAt = now, LastChecked = now };
        // A series added without a start season is "New episodes only": the absence is the answer.
        mode ??= EpisodeCursor.IsSeries(rowType) && fromSeason == null ? HuntCursor.NewEpisodesMode : null;
        db.WatchListItems.Add(item);
    }
    if (!patch)
    {
        item.Title = title!;
        if (!string.IsNullOrEmpty(poster)) item.PosterUrl = poster;
        if (!string.IsNullOrEmpty(synopsis)) item.Synopsis = synopsis;
        if (rating != null) item.Rating = rating;
        // The row follows the work its catalog id belongs to; a different work is never kept.
        if (chosenId != null) item.WorkId = chosenId;
        if (choice?.Work is { } w && w.PosterUrl == null && !string.IsNullOrEmpty(item.PosterUrl)) w.PosterUrl = item.PosterUrl;
    }
    if (patch || !existed)
    {
        if (status != null) item.Status = status;
        if (monitored != null) item.Monitored = monitored;
    }
    else
    {
        // An add never lowers a row that is already there: a rail's "planned, not monitored" (or one that reached the
        // row through a crosswalk) leaves a show the owner watches as it is. It may only start watching or monitoring it.
        if (status == "watching") item.Status = status;
        if (monitored == true) item.Monitored = true;
    }
    if (mode == null && fromSeason != null && HuntCursor.IsNewEpisodesOnly(item.MonitorMode)) mode = HuntCursor.OngoingMode;
    if (mode != null && mode != item.MonitorMode || mode == HuntCursor.NewEpisodesMode && item.NewEpisodesSince == null)
    {
        item.MonitorMode = mode!;
        item.NewEpisodesSince = HuntCursor.IsNewEpisodesOnly(mode) ? now : null;
        if (HuntCursor.IsNewEpisodesOnly(mode))
        {
            item.CursorSeason = null;
            item.CursorEpisode = null;
            item.NextEpisodeHint = null;
        }
    }
    if (f.Has("preferredResolution")) item.PreferredResolution = resolution;
    if (patch) item.LastChecked = now;
    if (f.Has("lastEpisode")) item.LastEpisode = lastEpisode;
    EpisodeCursor? cursor = null;
    if (fromSeason != null && (patch || EpisodeCursor.IsSeries(item.MediaType)))
    {
        cursor = new(fromSeason.Value, fromEpisode ?? 1);
        item.FromSeason = cursor.Value.Season;
        item.FromEpisode = cursor.Value.Episode;
        // A start on a later AniList entry ("season 3" on Attack on Titan Season 3 Part 2, or the beginning) is the entry's
        // first episode there as its show numbers it (Season 3 episode 13), never an episode the entry does not have.
        if (cursor.Value.Episode == 1) cursor = await ShowStartAsync(db, item, choice?.Work, cursor.Value, ct);
    }
    else if (patch && cursorSeason != null && cursorEpisode != null) cursor = new(cursorSeason.Value, cursorEpisode.Value);
    else if (patch && f.Has("lastEpisode"))
    {
        var copy = new WatchListItem { Title = item.Title, MediaType = item.MediaType, LastEpisode = lastEpisode, FromSeason = item.FromSeason, FromEpisode = item.FromEpisode };
        cursor = EpisodeCursor.Resolve(copy);
    }
    if (cursor != null)
    {
        item.CursorSeason = cursor.Value.Season;
        item.CursorEpisode = cursor.Value.Episode;
        item.NextEpisodeHint = cursor.Value.Query(item.Title);
    }
    item.UpdatedAt = now;
    item.NextCheckAt = item.Monitored == true && item.Status is "watching" or "planned" ? now : null;
    item.NextCheckReason = item.NextCheckAt == null ? null : "next check";
    if (EpisodeCursor.Resolve(item) != previousCursor || item.PreferredResolution != previousResolution)
    {
        item.SeederWaitSince = null;
        item.CursorMisses = 0;
    }
    await db.SaveChangesAsync(ct);
    // The row numbers its show as the page does: a work with nothing older is never read in the old numbering.
    if (item.WorkId != null) await AnimeNumberingReconciler.StampFreshAsync(db, item.WorkId, ct);
    // The provider record read for a new or newly identified work: its names, ids and links go through the one writer.
    if (choice is { Work: { } saved, Record: { } record }) await names.RefreshAsync(saved.WorkKey, record, fetch: false, ct);
    if (EpisodeCursor.AwaitingFirstNewEpisode(item))
        await NewEpisodes.PinAsync(db, airDates, item, TimeSpan.FromSeconds(5), ct);
    wake.Wake();
    // The row's linked work names the page it opens.
    var linked = item.WorkId == null ? null : choice?.Work is { } chosen && chosen.Id == item.WorkId ? chosen.WorkKey
        : await db.Works.Where(x => x.Id == item.WorkId).Select(x => x.WorkKey).FirstOrDefaultAsync(ct);
    return Ok(new { item = WithWorkKey(LibraryJson.Row(item), linked) });
    }
}

/// <summary>The work a new row links to, the row's type, the provider record read for it, or why the add is refused.</summary>
/// <param name="Provider">The catalog the row's external id belongs to ("" when none), part of the row's identity.</param>
private sealed record WorkChoice(Work? Work, string RowType, MediaMetadata? Record = null, string? Conflict = null, string Provider = "");

/// <summary>
/// The work a new row belongs to, so the hunter and on-demand grabs carry its catalog identity: the title page's
/// work (filled with the supplied identity when it has none), else the work holding this catalog id, else a new work
/// read from that provider so its format (film or series), anime verdict and names are stored from the start. An
/// AniList id is what an anime row's external id has always been. A keyed work that already has a different identity
/// is never attached silently: the work holding the supplied identity is used, else the add is refused. No catalog
/// id and no work leaves the row unlinked, as before. The work is tracked; the caller's save writes it.
/// </summary>
private async Task<WorkChoice> WorkFor(TorrentFlowDbContext db, string? workKey, string? provider, string? providerId, string type,
    string externalId, string title, string? poster, string? formatHint, CancellationToken ct)
{
    var identity = TitleIdentity.From(provider, providerId)
        ?? (type == "anime" && int.TryParse(externalId, out var anilist) && anilist > 0 ? new("anilist", externalId) : null);
    var key = workKey?.Trim().ToLowerInvariant() is { Length: > 0 } k ? k
        : externalId.StartsWith("work:", StringComparison.Ordinal) ? externalId[5..] : null;
    var keyed = key == null ? null : await db.Works.FirstOrDefaultAsync(w => w.WorkKey == key, ct);
    if (identity == null) return new(keyed, keyed != null ? RowType(type, keyed.Format, keyed.Provider) : type);
    // The row's external id is this catalog's id only when it is the supplied one (a "work:" key is no catalog's).
    var rowProvider = identity.ProviderId == externalId ? identity.Provider : "";
    var holder = await db.Works.FirstOrDefaultAsync(w => w.Provider == identity.Provider && w.ProviderId == identity.ProviderId &&
        (w.MediaType == type || identity.Provider == "anilist" || type == "anime"), ct);
    if (keyed != null && (keyed.Id == holder?.Id || Same(keyed, identity))) return new(keyed, RowType(type, keyed.Format, keyed.Provider), Provider: rowProvider);
    if (holder != null)
    {
        if (keyed != null) logger?.LogInformation("Watchlist add for {WorkKey} carries {Provider}:{ProviderId}, which {Holder} holds; linked to {Holder}",
            keyed.WorkKey, identity.Provider, identity.ProviderId, holder.WorkKey, holder.WorkKey);
        return new(holder, RowType(type, holder.Format, holder.Provider), Provider: rowProvider);
    }
    if (keyed?.Provider != null)
        return new(null, type, Conflict: "This title is already in your library under a different catalog entry.");

    var record = await RecordAsync(identity, type, ct);
    var format = WorkFormats.Of(record) ?? Format(formatHint) ?? WorkFormats.FromMediaType(type);
    var anime = record != null ? (bool?)AnimeIdentity.IsAnime(record) : AnimeIdentity.IsAnime(identity.Provider, null, identity.ProviderId) ? true : null;
    var mediaType = identity.Provider == "anilist" ? format == WorkFormat.Movie ? "movie" : "anime" : type;
    if (keyed != null)
    {
        // One library per show (WorkKinds.AnimeVerdict), read before the identity is attached so the work reads as it did.
        if (keyed.Anime == null && anime == false && keyed.IsAnime() == true && await AnimeFiling.PathAsync(db, keyed.Id, keyed.WorkKey, ct) is { } filed)
        {
            anime = WorkKinds.AnimeVerdict(false, true, filedInAnimeLibrary: true);
            AnimeFiling.LogKept(logger, keyed.WorkKey, identity.Provider, filed);
        }
        // A work with no catalog identity takes the one supplied: no other work holds it.
        keyed.Provider = identity.Provider;
        keyed.ProviderId = identity.ProviderId;
        keyed.Format ??= format;
        keyed.Anime ??= anime;
        keyed.OriginalLanguage ??= WorkFormats.LanguageOf(record);
        keyed.UpdatedAt = DateTime.UtcNow;
        return new(keyed, RowType(type, keyed.Format, keyed.Provider), record, Provider: rowProvider);
    }
    key ??= WorkKeySlug.WorkKeyFor(record?.Title ?? title, record?.Year);
    // A key another work already holds names this work only when that work is this identity (crosswalked to it);
    // otherwise the new work takes a key of its own catalog id, so the add never fails on the key.
    if (await db.Works.FirstOrDefaultAsync(w => w.WorkKey == key, ct) is { } taken)
    {
        if (Same(taken, identity)) return new(taken, RowType(type, taken.Format, taken.Provider), Provider: rowProvider);
        key = $"{key}-{identity.Provider}-{identity.ProviderId}".ToLowerInvariant();
    }
    var now = DateTime.UtcNow;
    var created = new Work { Id = Ids.New(), WorkKey = key, CanonicalTitle = record?.Title ?? title, MediaType = mediaType, Year = record?.Year,
        NamesJson = (record != null ? WorkNames.Of(record) : WorkNames.Legacy(title, null, identity.Provider)).ToJson(),
        IdsJson = (record?.Ids ?? new()).Merge(WorkIds.From(identity.Provider, identity.ProviderId)).ToJson() ?? "{}",
        Format = format, Anime = anime, OriginalLanguage = WorkFormats.LanguageOf(record),
        Provider = identity.Provider, ProviderId = identity.ProviderId, PosterUrl = poster ?? record?.PosterUrl, CreatedAt = now, UpdatedAt = now };
    db.Works.Add(created);
    return new(created, RowType(type, format, identity.Provider), record, Provider: rowProvider);
}

/// <summary>Whether the keyed work already is, or is crosswalked to, the supplied identity.</summary>
private static bool Same(Work work, TitleIdentity identity)
{
    if (work.Provider == identity.Provider && work.ProviderId == identity.ProviderId) return true;
    var mine = (WorkIds.FromJson(work.IdsJson) ?? new()).Merge(WorkIds.From(work.Provider, work.ProviderId));
    var theirs = WorkIds.From(identity.Provider, identity.ProviderId);
    return theirs.Tmdb != null && theirs.Tmdb == mine.Tmdb || theirs.AniList != null && theirs.AniList == mine.AniList
        || theirs.Mal != null && theirs.Mal == mine.Mal || theirs.Imdb != null && string.Equals(theirs.Imdb, mine.Imdb, StringComparison.OrdinalIgnoreCase);
}

/// <summary>An AniList row is "anime" (a series the hunter walks) unless its work is a film; other rows keep their type.</summary>
private static string RowType(string type, WorkFormat? format, string? provider) =>
    format == WorkFormat.Movie && (type == "anime" || provider == "anilist") ? "movie"
    : type == "movie" && provider == "anilist" && format is WorkFormat.Series ? "anime"
    : type;

private static WorkFormat? Format(string? hint) =>
    Enum.TryParse<WorkFormat>(hint, ignoreCase: true, out var format) && Enum.IsDefined(format) ? format : WorkFormats.FromAniList(hint);

/// <summary>The provider's own record, within 3 s; null when it can't be read (the work's first grab or open asks again).</summary>
private async Task<MediaMetadata?> RecordAsync(TitleIdentity identity, string type, CancellationToken ct)
{
    if (!IMetadataResolver.SupportsProvider(identity.Provider)) return null;
    using var budget = CancellationTokenSource.CreateLinkedTokenSource(ct);
    budget.CancelAfter(TimeSpan.FromSeconds(3));
    try
    {
        var record = await metadata.GetByIdAsync(identity.Provider, type == "movie" ? "movie" : "tv", identity.ProviderId, budget.Token);
        return record != null && record.Source == identity.Provider && record.ExternalId == identity.ProviderId ? record : null;
    }
    catch (Exception error) when (!ct.IsCancellationRequested)
    {
        logger?.LogInformation("Could not read {Provider}:{ProviderId} for a watchlist add: {Error}", identity.Provider, identity.ProviderId, error.Message);
        return null;
    }
}

private static bool IsUniqueViolation(DbUpdateException error) =>
    error.InnerException is Microsoft.Data.Sqlite.SqliteException { SqliteExtendedErrorCode: 2067 or 1555 };

/// <summary>
/// An unlinked row saved before rows named their catalog, reused only when it is this same title: the same type and id,
/// and the same title once normalized. TMDB movie 437 (Cube 2) is never taken over by AniList film 437 (Perfect Blue).
/// </summary>
private static async Task<WatchListItem?> LegacyRowAsync(TorrentFlowDbContext db, string type, string externalId, string title, CancellationToken ct)
{
    var key = WorkKeySlug.WorkKeyFor(title);
    if (key.Length == 0) return null;
    var rows = await db.WatchListItems.Where(x => x.UserId == LocalUser.Id && x.MediaType == type && x.ExternalId == externalId &&
        x.Provider == "" && x.WorkId == null).ToListAsync(ct);
    return rows.FirstOrDefault(x => WorkKeySlug.SameKey(WorkKeySlug.WorkKeyFor(x.Title), key));
}

